"""Apertus API note-revision diagnostic. run(globals()) in the configured Notebook.

Credentials stay in memory. No training or local student weights are loaded.
The embedded v24 polynomial auditors and prompts are reused unchanged.
"""
import base64, hashlib, json, os, re, sys, threading, time, urllib.request
import urllib.error, urllib.parse, zipfile, zlib
from pathlib import Path

def setup(work):
    payload=zlib.decompress(base64.b64decode(BUNDLE))
    if hashlib.sha256(payload).hexdigest()!=BUNDLE_SHA: raise RuntimeError('Runtime payload changed')
    root=work/'api-v25-auditors'/BUNDLE_SHA[:12];root.mkdir(parents=True,exist_ok=True)
    for name,source in json.loads(payload).items():
        if Path(name).name!=name or not name.endswith('.py'): raise RuntimeError('Invalid embedded path')
        p=root/name
        if p.exists() and p.read_text()!=source: raise RuntimeError('Auditor bytes changed')
        p.write_text(source,encoding='utf-8')
    # A Notebook may have imported other revisions of the same module names.
    for name in json.loads(payload): sys.modules.pop(name[:-3],None)
    sys.path.insert(0,str(root))
    from rr_common import sealed,check_seal,atomic_json,read,digest,put_once
    from cf_cases import property_prompt,memory_prompt,repair_prompt,prose_prompt,grounded,property_truth,ideal_action,ROLES
    from cf_memory import initial,apply_action,attach_proposal,proposal_audit,active_note,followup,attach_reflection
    from rr_evaluate import math_audit
    return locals()

def config(ns):
    cfg=ns.get('ZIP_API_CONFIG',{})
    if not isinstance(cfg,dict): raise RuntimeError('ZIP_API_CONFIG must be a dict')
    def pick(names):
        for n in names:
            v=ns.get(n) or os.environ.get(n)
            if isinstance(v,str) and v.strip(): return v.strip()
        return None
    key=cfg.get('api_key') or pick(('APERTUS_API_KEY','TEACHER_API_KEY','OPENAI_API_KEY','API_KEY','api_key'))
    url=cfg.get('base_url') or pick(('APERTUS_BASE_URL','TEACHER_BASE_URL','OPENAI_BASE_URL','API_BASE_URL','BASE_URL','base_url'))
    model=cfg.get('model') or pick(('APERTUS_API_MODEL','APERTUS_MODEL','TEACHER_MODEL','OPENAI_MODEL','API_MODEL'))
    for n in ('apertus_client','teacher_client','openai_client','client'):
        c=ns.get(n)
        if c is not None and hasattr(c,'base_url'):
            url=url or str(c.base_url)
            k=getattr(c,'api_key',None)
            if hasattr(k,'get_secret_value'): k=k.get_secret_value()
            if isinstance(k,str): key=key or k
    if not model:
        candidate=pick(('MODEL','MODEL_ID','model','model_id'))
        if candidate and 'apertus' in candidate.lower() and '0.5' not in candidate: model=candidate
    if not key or not url:
        missing=[]
        if not key: missing.append('api_key（从你现有的 key 变量引用）')
        if not url: missing.append('base_url（服务商的 API 地址）')
        raise RuntimeError('未识别到 '+ '、'.join(missing)+'。在同一 Notebook 设置 ZIP_API_CONFIG={"api_key":已有key变量,"base_url":服务商地址,"model":模型名}；不要把 key 发给我。')
    p=urllib.parse.urlsplit(url)
    if p.scheme not in ('https','http') or not p.hostname or p.username or p.password or p.query or p.fragment:
        raise RuntimeError('base_url must be a plain API endpoint without credentials/query')
    if p.scheme=='http' and p.hostname not in ('localhost','127.0.0.1','::1'): raise RuntimeError('Remote API requires HTTPS')
    token_field=cfg.get('token_field','max_tokens')
    if token_field not in ('max_tokens','max_completion_tokens'): raise RuntimeError('Unsupported token_field')
    budget=int(cfg.get('max_tokens',512))
    if not 256<=budget<=2048: raise RuntimeError('max_tokens must be 256..2048')
    extra=cfg.get('extra_body',{})
    if not isinstance(extra,dict) or set(extra)-{'chat_template_kwargs','reasoning_effort','enable_thinking'}:
        raise RuntimeError('Only explicit thinking options are allowed in extra_body')
    return dict(key=key,url=url.rstrip('/'),model=model,token_field=token_field,budget=budget,extra=extra)

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,*args,**kw): return None

def request(cfg,path,body=None):
    req=urllib.request.Request(cfg['url']+path,data=None if body is None else json.dumps(body).encode(),
        headers={'Authorization':'Bearer '+cfg['key'],'Content-Type':'application/json','User-Agent':'lain-zip-api-v25'})
    try:
        with urllib.request.build_opener(NoRedirect()).open(req,timeout=90) as r: return json.load(r)
    except urllib.error.HTTPError as e:
        # Provider error bodies / request reprs are not printed or persisted.
        raise RuntimeError('API HTTP '+str(e.code)+'；请核对服务商的模型名、地址与 token_field。请求未自动重试。') from None
    except Exception:
        raise RuntimeError('API 连接或响应解析失败；请求未自动重试，未保存错误正文。') from None

def resolve_model(cfg):
    if not cfg['model']:
        listing=request(cfg,'/models')
        names=[x.get('id','') for x in listing.get('data',[]) if isinstance(x,dict)]
        candidates=[n for n in names if 'apertus' in n.lower() and '0.5' not in n and re.search(r'(8|70)b',n,re.I)]
        candidates.sort(key=lambda n:('1.5' not in n,'8b' not in n.lower(),n))
        if not candidates: raise RuntimeError('此端点没有识别到 Apertus 8B/70B；请设置 ZIP_API_CONFIG["model"] 为可调用的 Apertus 模型 ID。')
        cfg['model']=candidates[0]
    if 'apertus' not in cfg['model'].lower() or '0.5' in cfg['model']:
        raise RuntimeError('本轮需要较强 Apertus。配置的 model 未识别为较强 Apertus；请填服务商提供的实际 ID。')
    return cfg

def parse_choice(text,allowed,capped=False):
    if capped:return None
    text=text.strip()
    if text in allowed:return text
    try:
        obj=json.loads(text)
        if isinstance(obj,dict) and obj.get('action') in allowed:return obj['action']
    except (ValueError,TypeError):pass
    return None # Never infer a choice from prose containing several candidates.

class API:
    def __init__(self,cfg,out,h):
        self.cfg,self.out,self.h=cfg,out,h;self.calls=0
        self.out.mkdir(parents=True,exist_ok=True)
    def ask(self,phase,c,messages):
        public={k:v for k,v in self.cfg.items() if k!='key'}
        body={'model':self.cfg['model'],'messages':messages,self.cfg['token_field']:self.cfg['budget'],**self.cfg['extra']}
        ident=self.h['digest']({'config':public,'phase':phase,'case':c['id'],'body':body})
        path=self.out/'raw'/(ident+'.json')
        if path.exists():return self.h['check_seal'](self.h['read'](path))
        # Count every attempted POST across resumes, including ambiguous interrupted calls.
        attempts=self.out/'attempts';attempts.mkdir(exist_ok=True)
        if len(list(attempts.glob('*.json')))>=PLAN['maxCalls']:raise RuntimeError('72次 API 请求上限已到；已保存的原文保留。')
        attempt=attempts/(ident+'-'+str(time.time_ns())+'.json')
        self.h['atomic_json'](attempt,{'requestId':ident,'status':'pending','uncertainPreviousAttempt':bool(list(attempts.glob(ident+'-*.json')))})
        self.calls+=1;print('[Apertus API] '+str(len(list(attempts.glob('*.json'))))+'/72 | '+phase,flush=True)
        done=threading.Event()
        def progress():
            while not done.wait(20):print('[Apertus API] 等待服务商响应 | '+phase,flush=True)
        t=threading.Thread(target=progress,daemon=True);t.start()
        try: response=request(self.cfg,'/chat/completions',body)
        finally:done.set();t.join(timeout=1)
        choices=response.get('choices',[])
        if not choices or not isinstance(choices[0],dict):raise RuntimeError('API 没有返回 choices；未写入伪造原文。')
        first=choices[0];message=first.get('message',{});raw=message.get('content')
        if raw is None:raw=''
        if not isinstance(raw,str):raise RuntimeError('API content is not a string')
        record=self.h['sealed']({'recordId':'api-'+ident,'phase':phase,'caseCardId':c['card']['id'],
            'request':body,'responseModel':response.get('model'),'usage':response.get('usage'),
            'systemFingerprint':response.get('system_fingerprint'),'providerResponseId':response.get('id'),
            'finishReason':first.get('finish_reason'),'reasoningRaw':message.get('reasoning_content') or message.get('reasoning'),
            'studentOutput':{'raw':raw,'tokenCapReached':first.get('finish_reason')=='length'},
            'expectedActionSuppliedToModel':False,'fixtureOnly':False})
        self.h['put_once'](path,record) # Preserve raw before any audit or memory edit.
        self.h['atomic_json'](attempt,{'requestId':ident,'status':'committed','recordHash':record['hash']})
        return record
    def choose(self,phase,c,messages,allowed):
        messages=[dict(x) for x in messages]
        messages[0]['content']+=' Return ONLY one of: '+', '.join(allowed)+'.'
        record=self.ask(phase,c,messages)
        action=parse_choice(record['studentOutput']['raw'],allowed,record['studentOutput']['tokenCapReached'])
        return record,action

def episode(api,c,h):
    folder=api.out/'episodes'/c['id'];folder.mkdir(parents=True,exist_ok=True)
    summary=folder/'summary.json'
    if summary.exists():return h['check_seal'](h['read'](summary))
    before=h['initial'](c['card']);h['put_once'](folder/'00-old-note.json',before)
    pre,preaction=api.choose('before',c,h['memory_prompt'](c),('KEEP','RETRACT'))
    props={};property_records={}
    for role in h['ROLES']:
        r,a=api.choose(role,c,h['property_prompt'](c,role),('ZERO','POSITIVE','NEGATIVE') if role.endswith('_sign') else ('NONE','ONCE','TWICE'))
        props[role]=a or 'INVALID';property_records[role]=r['recordId']
    r,action=api.choose('after',c,h['memory_prompt'](c,props),('KEEP','RETRACT'))
    # Invalid model output cannot be silently promoted to KEEP/RETRACT.
    after=before;accepted=False;proposal=None
    if action:
        d={k:v for k,v in r.items() if k!='hash'};d['action']=action;d=h['sealed'](d)
        after=h['apply_action'](before,d)
    h['put_once'](folder/'01-after-action.json',after)
    if action=='RETRACT':
        proposal=api.ask('replacement',c,h['repair_prompt'](c,props,action))
        audit=h['proposal_audit'](c,proposal)
        after=h['attach_proposal'](after,proposal,audit);accepted=audit['accepted']
        h['put_once'](folder/'02-replacement-audit.json',h['sealed'](audit))
    if c['kind'] in ('counterexample','correct_source_rule'):
        prose=api.ask('reflection',c,h['prose_prompt'](c,props,action or 'INVALID',None if proposal is None else proposal['studentOutput']['raw']))
        after=h['attach_reflection'](after,prose)
    h['put_once'](folder/'03-new-note.json',after)
    after=h['check_seal'](h['read'](folder/'03-new-note.json')) # Actually read persisted note back.
    follow=[]
    if c['kind'] in ('counterexample','correct_source_rule'):
        for variable,multiplier in (('q',1),('z',2)):
            results={}
            for arm,mem,no_note in (('no_note',before,True),('old_note',before,False),('new_note',after,False)):
                task,messages=h['followup'](mem,variable,no_note,multiplier)
                ans=api.ask('follow_'+variable+'_'+arm,c,messages)
                results[arm]={'recordId':ans['recordId'],'audit':h['math_audit'](task,ans)}
            follow.append({'variable':variable,'multiplier':multiplier,'results':results})
    ground=h['grounded'](c,props)
    correctnew=sum(x['results']['new_note']['audit']['correct'] for x in follow)
    helped=sum(not x['results']['old_note']['audit']['correct'] and x['results']['new_note']['audit']['correct'] for x in follow)
    row=h['sealed']({'caseId':c['id'],'kind':c['kind'],'inheritedNote':True,'apiAuthoredOriginal':False,
        'beforeAction':preaction,'afterAction':action,'properties':props,'propertyRecordIds':property_records,
        'groundedContradiction':ground,'correctActionForEvidence':action==h['ideal_action'](c),
        'replacementAccepted':accepted,'oldHash':before['hash'],'newHash':after['hash'],'followup':follow,
        'newNoteCorrectAnswers':correctnew,'oldWrongToNewCorrect':helped,
        'candidateClosedLoop':bool(ground and action=='RETRACT' and accepted and correctnew==2),
        'freeReflectionRequiresHumanSemanticReview':True})
    h['put_once'](summary,row);return row

def package(out):
    target=out.parent/('Lain-Zip-Apertus-API-Review-'+out.name.rsplit('-',1)[-1]+'.zip')
    temp=target.with_suffix('.zip.tmp')
    with zipfile.ZipFile(temp,'w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted(out.rglob('*')):
            if p.is_file():z.write(p,p.relative_to(out))
    with zipfile.ZipFile(temp) as z:
        if z.testzip():raise RuntimeError('Review ZIP CRC failed')
    os.replace(temp,target);return target

def run(namespace):
    work=Path(namespace.get('ZIP_API_WORK','/mnt/workspace/lain-zip-pilot'))
    work.mkdir(parents=True,exist_ok=True);h=setup(work)
    cfg=resolve_model(config(namespace))
    public={k:v for k,v in cfg.items() if k!='key'}
    binding=h['digest']({'plan':PLAN,'publicConnection':public,'bundle':BUNDLE_SHA,'runner':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()})
    out=work/('zip-apertus-api-'+binding[:12]);out.mkdir(exist_ok=True)
    protocol=h['sealed']({'plan':PLAN,'publicConnection':public,'binding':binding,
        'apiWeightsPinnedByHash':False,'APIModelChangesMustBeReviewed':True,'maxAttemptedPOSTs':72,
        'noCorrectAnswersInPrompts':True,'sourceColdOwnAnswerNotInherited':True})
    h['put_once'](out/'protocol.json',protocol)
    print('测试模型：'+cfg['model']+'；零训练；最多72次请求；旧参数未加载。',flush=True)
    print('目录：'+str(out),flush=True)
    if (out/'result.json').exists():
        result=h['check_seal'](h['read'](out/'result.json'));print(json.dumps(result,ensure_ascii=False,indent=2));print('审阅 ZIP：'+str(package(out)));return result
    api=API(cfg,out,h)
    try:
        # This response is genuinely written by the API model, before seeing the old note.
        c=PLAN['cases'][0]
        own=api.ask('own_cold_original',c,[{'role':'system','content':'Write ONE collected algebraic expression. Use * and **; an equality chain is allowed.'},{'role':'user','content':'Collect: '+c['card']['left']+'. v is real.'}])
        own_audit=h['math_audit']({'expression':c['card']['left'],'scope':'real_polynomial'},own)
        rows=[episode(api,c,h) for c in PLAN['cases']]
        decisive=[r for r in rows if r['kind']=='counterexample'];controls=[r for r in rows if r['kind']!='counterexample']
        result=h['sealed']({'complete':True,'requestedModel':cfg['model'],'actualResponseModels':sorted({h['read'](p).get('responseModel') or 'UNREPORTED' for p in (out/'raw').glob('*.json')}),
            'trainingUpdates':0,'attemptedPOSTs':len(list((out/'attempts').glob('*.json'))),'savedResponses':len(list((out/'raw').glob('*.json'))),
            'ownColdOriginalCorrect':own_audit['correct'],'ownUnnoticedErrorRepairProven':False,
            'inheritedDecisiveCases':len(decisive),'correctGroundedChecks':sum(r['groundedContradiction'] for r in decisive),
            'withdrawals':sum(r['afterAction']=='RETRACT' for r in decisive),'verifiedNewFormulas':sum(r['replacementAccepted'] for r in decisive),
            'candidateClosedLoops':sum(r['candidateClosedLoop'] for r in decisive),'oldWrongToNewCorrect':sum(r['oldWrongToNewCorrect'] for r in decisive),
            'correctEvidenceControls':sum(r['correctActionForEvidence'] for r in controls),'evidenceControls':len(controls),
            'rows':rows,'statisticalSignificanceClaimed':False,'generalRobustnessClaimed':False,
            'interpretation':'继承旧错笔记的修订测试；API自由文本接口与本地受约束打分不同。候选闭环须读反思原文，不能直接证明修复自己的未察觉错误。'})
        h['put_once'](out/'result.json',result)
        print(json.dumps({k:v for k,v in result.items() if k not in ('rows','hash')},ensure_ascii=False,indent=2),flush=True)
        return result
    except KeyboardInterrupt:
        print('已暂停。重跑同一代码复用已提交原文；未返回的请求可能已计费，重跑将记录重试。',flush=True)
        return None
    finally:
        print('审阅 ZIP：'+str(package(out))+'（CRC已校验，不含key/权重）',flush=True)

if __name__=='__main__':run(globals())
